# Objetivo (defeat Serpent): al completarse la misión final
# (estado 0xF8, id 19) mission_complete_on_report (0x02031028)
# pone AMBOS bits (derivado estático; validar en E2E):
# CORREGIDO 2026-09-02 (agente exp290-299 + exp275): los ids 17-19 de la
# tabla son QUESTS (17=Find the Flower, 18=Trim the Weeds, 19=Find the
# Boy) y EB.7/EC.0 era completar 'Find the Boy'. La mision 16 (Destroy
# Model W) nunca se reporta. Fin real: Serpent forma 2 muerta ->
# 0x02104602.3 (guion de D-5; .2 = forma 1) y, tras la explosion, el
# evento de la VM del epilogo 0x021045CA.5 (VERIFICADO 298f/275).
GOAL_BITS = [(0x021045CA, 5)]
GOAL_BITS_ALT = [(0x02104602, 2), (0x02104602, 3)]

# --- Buzón de pickups respawneables (parche rom.py PICKUP_MAILBOX_*;
# agente exp360-369). u32 contador en PICKUP_MAILBOX_ADDR (sube 1 por
# recogida de un refill instanciado desde el layout) + anillo de
# PICKUP_MAILBOX_SLOTS entradas u32 [u8 subárea, u8 índice de coords,
# u8 role, 0] en +4 (entrada k del contador -> +4 + (k %% SLOTS)*4).
# Las locations con detect ['mailbox', sub, idx] se envían cuando
# aparece su (sub, idx); el cliente filtra repeticiones (respawn) y
# re-sincroniza si el contador retrocede (reset del emulador).
PICKUP_MAILBOX_ADDR = 0x020CB500
PICKUP_MAILBOX_SLOTS = 8
# Iconos de item en el mundo (rom.py ICON_*, set AP 261; exp560-569): tabla
# por subárea que escribe el cliente: u8 sub, u8 flags (bit0 válida), u16 pad,
# u8 code[128] (índice de coords -> ICON_CODES[nombre] = anim+1; 0 = sin
# cambio), 32 B bitmap 'ya enviado' (bit = idx -> aspecto vanilla) y, desde
# 2026-09-07 (rom.py PICKUP_AP), en +0xA4 32 B bitmap 'present' (bit = idx ->
# location del multiworld aún no enviada: el pickup NO aplica su efecto
# vanilla; se escribe aunque los iconos estén apagados). Cada
# location física lleva 'icon': [sub, idx] (su índice en la tabla de coords
# de la sala = el que el cave lee de la lista de spawns 0x021081F4).
